mapper.select:
SELECT 
FROM region_history_tags rht
JOIN regions r ON r.region_id = rht.region_id
JOIN history_tags ht ON ht.tag_id = rht.tag_id


        AND r.sido_name = #{sidoName}


        AND r.gugun_name = #{gugunName}


        AND (
            ht.tag_name LIKE CONCAT('%', #{keyword}, '%')
            OR rht.evidence_summary LIKE CONCAT('%', #{keyword}, '%')
            OR rht.evidence_places LIKE CONCAT('%', #{keyword}, '%')
        )


        AND ht.tag_type = #{tagType}


        AND rht.weight >= #{minWeight}


        AND rht.needs_review = #{needsReview}


ORDER BY r.sido_name, r.gugun_name, rht.weight DESC, ht.tag_type, ht.tag_name
LIMIT #{limit} OFFSET #{offset}
